import os
import time
import hashlib
import threading
import tempfile
from pathlib import Path
from functools import wraps
from collections import defaultdict

# Rate limiting configuration
RATE_LIMIT_WINDOW = 60
MAX_REQUESTS_PER_WINDOW = 100
_request_counts = defaultdict(list)
_lock = threading.Lock()

def rate_limit(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        client_id = kwargs.get('client_id', 'anonymous')
        now = time.time()
        with _lock:
            _request_counts[client_id] = [
                t for t in _request_counts[client_id]
                if now - t < RATE_LIMIT_WINDOW
            ]
            if len(_request_counts[client_id]) >= MAX_REQUESTS_PER_WINDOW:
                raise RuntimeError(f"Rate limit exceeded for {client_id}")
            _request_counts[client_id].append(now)
        return func(self, *args, **kwargs)
    return wrapper

def retry(max_attempts=3, backoff_factor=0.5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except (IOError, OSError) as e:
                    last_exception = e
                    time.sleep(backoff_factor * (2 ** attempt))
            raise last_exception
        return wrapper
    return decorator


class SecureFileProcessor:
    """File processing service with secure temporary file handling."""

    def __init__(self, base_dir='/var/app/processing', temp_subdir='tmp'):
        self.base_dir = Path(base_dir)
        self.temp_dir = self.base_dir / temp_subdir
        self._ensure_directories()

    def _ensure_directories(self):
        self.base_dir.mkdir(parents=True, exist_ok=True)
        self.temp_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(str(self.temp_dir), 0o700)

    def _create_secure_temp(self, suffix=''):
        """Create a secure temporary file using OS-level guarantees."""
        fd, path = tempfile.mkstemp(
            dir=str(self.temp_dir),
            prefix='proc_',
            suffix=suffix
        )
        # mkstemp creates with 0o600 and returns an open fd
        # ensuring no race condition between creation and use
        return fd, Path(path)

    @retry(max_attempts=3)
    def _write_temp_file(self, fd, data):
        """Write data to temporary file descriptor."""
        try:
            with os.fdopen(fd, 'wb') as f:
                f.write(data)
        except Exception:
            try:
                os.close(fd)
            except OSError:
                pass
            raise

    def _validate_content(self, data):
        if len(data) > 50 * 1024 * 1024:
            raise ValueError("File too large (max 50MB)")
        if not data:
            raise ValueError("Empty content")
        return True

    @rate_limit
    def process_file(self, data, output_name, client_id='anonymous'):
        """Process uploaded file data with temporary staging."""
        self._validate_content(data)
        content_hash = hashlib.sha256(data).hexdigest()

        suffix = Path(output_name).suffix
        if suffix not in ('.txt', '.csv', '.json', '.xml'):
            suffix = '.dat'

        fd, temp_path = self._create_secure_temp(suffix)

        try:
            self._write_temp_file(fd, data)
            result = self._transform_content(temp_path)
            final_path = self._finalize(temp_path, output_name)
            return {'status': 'success', 'path': str(final_path), 'hash': content_hash}
        finally:
            if temp_path.exists():
                temp_path.unlink()

    @retry(max_attempts=2)
    def _transform_content(self, temp_path):
        """Apply transformations to the staged file."""
        with open(temp_path, 'rb') as f:
            content = f.read()
        # Simulate processing
        return hashlib.sha256(content).hexdigest()

    def _finalize(self, temp_path, output_name):
        """Move processed file to final destination."""
        safe_name = Path(output_name).name  # strip directory components
        final_path = self.base_dir / 'output' / safe_name
        final_path.parent.mkdir(parents=True, exist_ok=True)

        # Atomic rename within same filesystem
        os.rename(str(temp_path), str(final_path))
        return final_path

    @rate_limit
    def batch_process(self, file_list, client_id='anonymous'):
        """Process multiple files with shared rate limiting."""
        results = []
        for item in file_list:
            try:
                result = self.process_file(
                    data=item['data'],
                    output_name=item['name'],
                    client_id=client_id
                )
                results.append(result)
            except Exception as e:
                results.append({'status': 'error', 'name': item['name'], 'error': str(e)})
        return results


class TempFileManager:
    """Manages temporary file lifecycle with cleanup scheduling."""

    def __init__(self, temp_dir, max_age_seconds=3600):
        self.temp_dir = Path(temp_dir)
        self.max_age = max_age_seconds
        self._cleanup_lock = threading.Lock()

    def cleanup_stale(self):
        """Remove temporary files older than max_age."""
        now = time.time()
        with self._cleanup_lock:
            for entry in self.temp_dir.iterdir():
                if entry.is_file() and entry.name.startswith('proc_'):
                    age = now - entry.stat().st_mtime
                    if age > self.max_age:
                        entry.unlink()

    def get_temp_file(self, prefix='proc_', suffix='.tmp'):
        """Create a new managed temporary file."""
        fd, path = tempfile.mkstemp(
            dir=str(self.temp_dir),
            prefix=prefix,
            suffix=suffix
        )
        os.close(fd)
        return Path(path)
